import 'package:flutter/material.dart';
import '../widgets/parent_bottom_navigation.dart';
import '../widgets/lenyora_page_header.dart';
import 'package:file_picker/file_picker.dart';
import '../services/data_service.dart';

class ApplicationFormScreen extends StatefulWidget {const ApplicationFormScreen({super.key});@override State<ApplicationFormScreen> createState()=>_ApplicationFormScreenState();}
class _ApplicationFormScreenState extends State<ApplicationFormScreen>{final _form=GlobalKey<FormState>();final _learner=TextEditingController();final _age=TextEditingController();final _parent=TextEditingController();final _phone=TextEditingController();final _service=DataService();String _grade='Grade R';List<PlatformFile> _files=[];bool _busy=false;final _grades=const['Grade R','Grade 1','Grade 2','Grade 3','Grade 4','Grade 5','Grade 6','Grade 7'];
@override void dispose(){_learner.dispose();_age.dispose();_parent.dispose();_phone.dispose();super.dispose();}
Future<void> _pick()async{try{final result=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['pdf','jpg','jpeg','png'],allowMultiple:true,withData:true);if(result==null)return;for(final f in result.files){if(f.size>10*1024*1024)throw Exception('${f.name} is larger than 10 MB.');if(f.bytes==null)throw Exception('Could not read ${f.name}; try selecting it again.');}setState(()=>_files=[..._files,...result.files]);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
Future<void> _submit()async{if(!_form.currentState!.validate())return;if(_files.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Please select at least one supporting document.')));return;}setState(()=>_busy=true);try{await _service.submitApplication(learnerName:_learner.text,age:int.parse(_age.text),grade:_grade,parentName:_parent.text,phone:_phone.text,files:_files);if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Application submitted successfully.')));Navigator.pop(context);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Submission failed: $e')));}finally{if(mounted)setState(()=>_busy=false);}}
