PNG. Maximum 10 MB per file.'),const SizedBox(height:8),OutlinedButton.icon(onPressed:_busy?null:_pick,icon:const Icon(Icons.upload_file),label:const Text('Choose documents')),..._files.map((f)=>ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.insert_drive_file),title:Text(f.name,maxLines:1,overflow:TextOverflow.ellipsis),subtitle:Text('${(f.size/1024).toStringAsFixed(0)} KB'),trailing:IconButton(onPressed:()=>setState(()=>_files.remove(f)),icon:const Icon(Icons.close)))),const SizedBox(height:20),FilledButton.icon(onPressed:_busy?null:_submit,icon:const Icon(Icons.send),label:Text(_busy?'Submitting...':'Submit application')),const SizedBox(height:20)])))),
      bottomNavigationBar: const ParentBottomNavigation(currentIndex: 3),
    );
}
